import React, { useEffect, useState } from "react";
import { Routes, Route, Navigate, useNavigate } from "react-router-dom";
import axios from "axios";

import Login from "./pages/Login";
import SuperAdminDashboard from "./pages/SuperAdminDashboard";
import TeacherDashboard from "./pages/TeacherDashboard";
import StudentDashboard from "./pages/StudentDashboard";
import ProtectedRoute from "./components/ProtectedRoute";

// ✅ Updated for Admin Layout and nested pages
import AdminLayout from "./pages/frontend/Student/MainLayout";
import AdminDashboard from "./pages/frontend/Student/Dashboard";
import Courses from "./pages/frontend/Student/MyCourses";
import Assignments from "./pages/frontend/Student/Assignments";
import Sidebar from "./pages/frontend/Student/Sidebar";
import Skills from "./pages/frontend/Student/Skills";
import SkillProgressDetail from "./pages/frontend/Student/SkillProgressDetail";
import StudyGroups from "./pages/frontend/Student/StudyGroups";
import Schedule from "./pages/frontend/Student/Schedule";
import Settings from "./pages/frontend/Student/Settings";
// Add more pages if you have them...

function App() {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();

  useEffect(() => {
    const storedUser = JSON.parse(localStorage.getItem("user"));
    if (storedUser) setUser(storedUser);
    setLoading(false);
  }, []);

  const handleLogin = async (username, password) => {
    try {
      const res = await axios.post("http://localhost:5000/api/auth/login", {
        username,
        password,
      });
      const { token, user } = res.data;

      localStorage.setItem("token", token);
      localStorage.setItem("user", JSON.stringify(user));
      setUser(user);

      // Redirect based on role
      switch (user.role) {
        case "superadmin":
          navigate("/superadmin");
          break;
        case "admin":
          navigate("/admin");
          break;
        case "teacher":
          navigate("/teacher");
          break;
        case "student":
          navigate("/student");
          break;
        default:
          navigate("/");
      }
    } catch (err) {
      alert(err.response?.data?.message || "Login failed");
    }
  };

  const handleLogout = () => {
    localStorage.removeItem("token");
    localStorage.removeItem("user");
    setUser(null);
    navigate("/");
  };

  if (loading) {
    return <div>Loading...</div>;
  }

  if (!user) {
    return <Login onLogin={handleLogin} />;
  }

  return (
    <Routes>
      <Route path="/" element={<Navigate to={`/${user.role}`} />} />

      <Route
        path="/superadmin"
        element={
          <ProtectedRoute user={user} allowedRoles={["superadmin"]}>
            <SuperAdminDashboard user={user} logout={handleLogout} />
          </ProtectedRoute>
        }
      />

      {/* ✅ Nested routing for admin */}
      <Route
        path="/admin/*"
        element={
          <ProtectedRoute user={user} allowedRoles={["admin"]}>
            <AdminLayout user={user} logout={handleLogout} />
          </ProtectedRoute>
        }
      >
        <Route index element={<AdminDashboard user={user} />} />
        <Route path="courses" element={<Courses />} />
        <Route path="assignments" element={<Assignments />} />
        <Route path="sidebar" element={<Sidebar />} />
        <Route path="settings" element={<Settings />} />
        <Route path="skills" element={<Skills />} />
        <Route path="studygroups" element={<StudyGroups />} />
        <Route path="schedule" element={<Schedule />} />
        <Route path="skillprogressdetail" element={<SkillProgressDetail />} />
        {/* Add more nested admin pages here if needed */}
      </Route>

      <Route
        path="/teacher"
        element={
          <ProtectedRoute user={user} allowedRoles={["teacher"]}>
            <TeacherDashboard user={user} logout={handleLogout} />
          </ProtectedRoute>
        }
      />

      <Route
        path="/student"
        element={
          <ProtectedRoute user={user} allowedRoles={["student"]}>
            <StudentDashboard user={user} logout={handleLogout} />
          </ProtectedRoute>
        }
      />

      <Route path="*" element={<Navigate to={`/${user.role}`} />} />
    </Routes>
  );
}

export default App;
